def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'

    opp = [h[1] for h in history]
    own = [h[0] for h in history]

    last_opp = opp[-1]

    # Count consecutive opponent defections at the end
    opp_run_d = 0
    for i in range(n - 1, -1, -1):
        if opp[i] == 'D':
            opp_run_d += 1
        else:
            break

    # Count consecutive opponent cooperations at the end
    opp_run_c = 0
    for i in range(n - 1, -1, -1):
        if opp[i] == 'C':
            opp_run_c += 1
        else:
            break

    opp_def = sum(1 for x in opp if x == 'D')
    opp_coop = n - opp_def

    # Defect rarely, only against pure defectors or as a late-game exploitation
    if opp_def == 0:
        # Opponent never defected: cooperate, but exploit at the very end
        if n >= 96 and rng.random() < 0.7:
            return 'D'
        return 'C'

    if opp_coop == 0:
        return 'D'

    # Against a long streak of defections, stay in defection
    if opp_run_d >= 4:
        # Occasionally test for forgiveness every 5 rounds
        if opp_run_d % 5 == 0 and rng.random() < 0.15:
            return 'C'
        return 'D'

    # Short streak of defections: retaliate once, then try to return to cooperation
    if last_opp == 'D':
        if opp_run_d == 1:
            # single defection: retaliate
            return 'D'
        # two or three: sometimes forgive to break cycles
        if opp_run_d <= 3 and rng.random() < 0.35:
            return 'C'
        return 'D'

    # Opponent cooperated last round
    # If they have a history of frequent defection, be cautious
    if opp_def * 3 > n:
        # More than 1/3 defections: defect more often
        if rng.random() < 0.45:
            return 'D'
        return 'C'

    # If opponent's recent defection rate is moderate, occasional defensive defection
    if n >= 6:
        recent = opp[-6:]
        recent_def = sum(1 for x in recent if x == 'D')
        if recent_def >= 3:
            if rng.random() < 0.5:
                return 'D'
            return 'C'

    # Otherwise cooperate
    return 'C'
